// Generate Perplexity AI queries based on enrichment type
const topic = $input.item.json.topic;
const showName = $input.item.json.show_name;
const enrichmentType = $input.item.json.enrichment_type;

let queries = [];

if (enrichmentType === 'fan_theories') {
  queries = [
    `What are the most popular fan theories about ${topic} in ${showName}?`,
    `${showName} ${topic} fan theories and analysis`,
    `Hidden meanings and Easter eggs in ${showName} related to ${topic}`
  ];
} else if (enrichmentType === 'character_analysis') {
  queries = [
    `Deep character analysis of ${topic} in ${showName}`,
    `${topic} character arc and development in ${showName}`,
    `${topic} relationships and motivations in ${showName}`
  ];
} else if (enrichmentType === 'episode_analysis') {
  queries = [
    `Critical analysis of ${topic} episode in ${showName}`,
    `${showName} ${topic} themes and symbolism`,
    `Behind the scenes and production details for ${topic} in ${showName}`
  ];
} else {
  // Comprehensive enrichment
  queries = [
    `Comprehensive analysis of ${topic} in ${showName}`,
    `${showName} ${topic} fan theories and interpretations`,
    `${topic} character relationships and story arcs in ${showName}`,
    `Critical reception and impact of ${topic} in ${showName}`
  ];
}

return queries.map(query => ({
  json: {
    query: query,
    topic: topic,
    show_name: showName,
    enrichment_type: enrichmentType
  }
}));

