// Extract and structure Perplexity response
const response = $input.item.json;
const query = $input.item.json.query;

let enrichedData = {
  query: query,
  topic: $input.item.json.topic,
  show_name: $input.item.json.show_name,
  enrichment_type: $input.item.json.enrichment_type,
  content: '',
  citations: [],
  enriched_at: new Date().toISOString()
};

if (response.choices && response.choices.length > 0) {
  enrichedData.content = response.choices[0].message.content;

  // Extract citations if available
  if (response.citations) {
    enrichedData.citations = response.citations;
  }
}

return {
  json: enrichedData
};

// Combine all enriched data into a comprehensive analysis
const allItems = $input.all();

let combinedAnalysis = {
  topic: allItems[0].json.topic,
  show_name: allItems[0].json.show_name,
  enrichment_type: allItems[0].json.enrichment_type,
  enriched_at: new Date().toISOString(),
  queries_processed: allItems.length,
  comprehensive_analysis: '',
  all_citations: [],
  data_type: 'perplexity_enrichment'
};

// Combine all content
let contentSections = [];
allItems.forEach((item, index) => {
  contentSections.push(`\n### Query ${index + 1}: ${item.json.query}\n`);
  contentSections.push(item.json.content);

  if (item.json.citations && item.json.citations.length > 0) {
    combinedAnalysis.all_citations.push(...item.json.citations);
  }
});

combinedAnalysis.comprehensive_analysis = contentSections.join('\n\n');

// Remove duplicate citations
combinedAnalysis.all_citations = [...new Set(combinedAnalysis.all_citations)];

return {
  json: combinedAnalysis
};
